import { Component, OnDestroy, inject } from '@angular/core';
import { AbstractControl, FormBuilder, ReactiveFormsModule, ValidationErrors, Validators } from '@angular/forms';
import { HttpClient, HttpClientModule } from '@angular/common/http';
import { Subscription } from 'rxjs';
import { timeout } from 'rxjs/operators';

const TIME_LIMIT_MS = 2000;

// Validators.required accepts a value made of spaces, so trim first.
function requiredText(control: AbstractControl): ValidationErrors | null {
  return String(control.value ?? '').trim() ? null : { required: true };
}

function minTextLength(length: number) {
  return (control: AbstractControl): ValidationErrors | null => {
    const text = String(control.value ?? '').trim();
    return !text || text.length >= length ? null : { minlength: true };
  };
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [ReactiveFormsModule, HttpClientModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export default class AppComponent implements OnDestroy {
  private fb = inject(FormBuilder);
  private http = inject(HttpClient);
  private request?: Subscription;

  contactForm = this.fb.nonNullable.group({
    name: ['', [requiredText]],
    email: ['', [requiredText, Validators.pattern(/\S+@\S+\.\S+/)]],
    message: ['', [requiredText, minTextLength(10)]],
  });

  isSubmitting = false;
  successMessage = '';
  errorMessage = '';

  get f() {
    return this.contactForm.controls;
  }

  showError(field: 'name' | 'email' | 'message'): boolean {
    const control = this.f[field];
    return control.touched && control.invalid;
  }

  clearSuccess(): void {
    this.successMessage = '';
  }

  submit(): void {
    if (this.isSubmitting) return;

    this.successMessage = '';
    this.errorMessage = '';
    this.contactForm.markAllAsTouched();

    if (this.contactForm.invalid) {
      const firstInvalid = (['name', 'email', 'message'] as const).find((field) => this.f[field].invalid);
      if (firstInvalid) document.getElementById(firstInvalid)?.focus();
      return;
    }

    const { name, email, message } = this.contactForm.getRawValue();
    this.isSubmitting = true;
    this.request = this.http
      .post('https://jsonplaceholder.typicode.com/posts', {
        name: name.trim(),
        email: email.trim(),
        message: message.trim(),
      })
      .pipe(timeout(TIME_LIMIT_MS))
      .subscribe({
        next: () => {
          this.isSubmitting = false;
          this.successMessage = 'Your message has been sent. Thank you!';
          this.contactForm.reset();
        },
        error: (error: { name?: string }) => {
          this.isSubmitting = false;
          this.errorMessage = error?.name === 'TimeoutError'
            ? 'The server took too long. Please try again.'
            : 'Something went wrong. Please try again.';
        },
      });
  }

  ngOnDestroy(): void {
    this.request?.unsubscribe();
  }
}

export { AppComponent };

